-- Phase 32: a vendor's own offers (SPEC core 7, "Vendor Offers"). Table and CRUD only: no order
-- is priced with an offer yet.
-- Generated by drizzle-kit; the trigger at the end is hand-added:
--   INSERT  only by the shop's own account, and never already ended
--   UPDATE  only to end the offer, once, by the shop's own account; every term is frozen
--   DELETE  refused
CREATE TABLE "vendor_offers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vendor_id" uuid NOT NULL,
	"kind" "discount_kind" NOT NULL,
	"value" numeric(12, 2) NOT NULL,
	"max_discount_npr" numeric(12, 2),
	"min_cart_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"label" text NOT NULL,
	"starts_at" timestamp with time zone DEFAULT now() NOT NULL,
	"ends_at" timestamp with time zone,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"ended_at" timestamp with time zone,
	"ended_by_user_id" uuid,
	CONSTRAINT "vendor_offers_value_check" CHECK ("vendor_offers"."value" > 0 AND ("vendor_offers"."kind" <> 'PERCENTAGE' OR "vendor_offers"."value" <= 100)),
	CONSTRAINT "vendor_offers_max_discount_check" CHECK ("vendor_offers"."max_discount_npr" IS NULL OR ("vendor_offers"."kind" = 'PERCENTAGE' AND "vendor_offers"."max_discount_npr" > 0)),
	CONSTRAINT "vendor_offers_min_cart_check" CHECK ("vendor_offers"."min_cart_npr" >= 0),
	CONSTRAINT "vendor_offers_flat_min_cart_check" CHECK ("vendor_offers"."kind" <> 'FLAT' OR "vendor_offers"."min_cart_npr" >= "vendor_offers"."value"),
	CONSTRAINT "vendor_offers_label_check" CHECK (btrim("vendor_offers"."label") <> ''),
	CONSTRAINT "vendor_offers_dates_check" CHECK ("vendor_offers"."ends_at" IS NULL OR "vendor_offers"."ends_at" > "vendor_offers"."starts_at"),
	CONSTRAINT "vendor_offers_ended_check" CHECK (("vendor_offers"."ended_at" IS NULL) = ("vendor_offers"."ended_by_user_id" IS NULL))
);
