-- Hand-added. A vendor is never charged for a discount it did not switch on itself (SPEC core 7),
-- and the rule an order was priced with never changes underneath it.
CREATE FUNCTION guard_vendor_offer() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a vendor offer is ended, never deleted'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM vendors v WHERE v.id = NEW.vendor_id AND v.user_id = NEW.created_by_user_id
    ) THEN
      RAISE EXCEPTION 'a vendor offer is created by the vendor''s own account'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF NEW.ended_at IS NOT NULL THEN
      RAISE EXCEPTION 'a vendor offer is not created ended'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.id, NEW.vendor_id, NEW.kind, NEW.value, NEW.max_discount_npr, NEW.min_cart_npr,
      NEW.label, NEW.starts_at, NEW.ends_at, NEW.created_by_user_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.vendor_id, OLD.kind, OLD.value, OLD.max_discount_npr, OLD.min_cart_npr,
      OLD.label, OLD.starts_at, OLD.ends_at, OLD.created_by_user_id, OLD.created_at) THEN
    RAISE EXCEPTION 'the terms of a vendor offer never change: end it and create another'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.ended_at IS NOT NULL OR NEW.ended_at IS NULL THEN
    RAISE EXCEPTION 'a vendor offer is ended once and stays ended'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM vendors v WHERE v.id = NEW.vendor_id AND v.user_id = NEW.ended_by_user_id
  ) THEN
    RAISE EXCEPTION 'a vendor offer is ended by the vendor''s own account'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER vendor_offers_guard BEFORE INSERT OR UPDATE OR DELETE ON vendor_offers
  FOR EACH ROW EXECUTE FUNCTION guard_vendor_offer();
